function extensionOf(name: string) {
  const dot = name.lastIndexOf(".")
  return dot > 0 ? name.slice(dot + 1).toLowerCase() : ""
}

const CODE = new Set([
  "ts",
  "tsx",
  "js",
  "jsx",
  "mjs",
  "py",
  "rb",
  "go",
  "rs",
  "java",
  "kt",
  "swift",
  "c",
  "cpp",
  "h",
  "cs",
  "php",
  "sh",
  "sql",
  "json",
  "yaml",
  "yml",
  "toml",
  "html",
  "css",
  "prisma",
  "graphql",
])

/** Groups a file by MIME type, then by extension, to pick its icon. */
function fileKind(name: string, type = ""): FileKind {
  const ext = extensionOf(name)
  if (type.startsWith("image/")) return "image"
  if (type.startsWith("video/")) return "video"
  if (type.startsWith("audio/")) return "audio"
  if (CODE.has(ext)) return "code"
  if (["csv", "tsv", "xls", "xlsx", "numbers"].includes(ext)) return "sheet"
  if (["zip", "tar", "gz", "tgz", "rar", "7z"].includes(ext)) return "archive"
  if (["png", "jpg", "jpeg", "gif", "webp", "svg", "avif", "heic"].includes(ext)) return "image"
  if (["mp4", "mov", "webm", "mkv"].includes(ext)) return "video"
  if (["mp3", "wav", "m4a", "ogg", "flac"].includes(ext)) return "audio"
  if (["pdf", "txt", "md", "doc", "docx", "rtf", "pages"].includes(ext) || type.startsWith("text/"))
    return "text"
  return "file"
}

const clamp01 = (n: number | undefined) => Math.min(1, Math.max(0, n ?? 0))

const UNITS = ["B", "KB", "MB", "GB", "TB"]

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const NBSP = " "

/** `31.4 of 96.0 MB`: both numbers in the unit of the total, so the pair reads at a glance. */
export function formatBytesOf(done: number, total: number) {
  let unit = 0
  let scale = 1
  while (total / scale >= 1000 && unit < UNITS.length - 1) {
    scale *= 1000
    unit += 1
  }
  const fmt = (n: number) => {
    const v = n / scale
    return unit === 0 ? String(Math.round(v)) : v.toFixed(1)
  }
  return `${fmt(done)} of ${fmt(total)}${NBSP}${UNITS[unit]}`
}

const NBSP2 = "\u00a0"

/** `4200` becomes `4.2 KB`. Decimal units, the way macOS and most upload UIs count. */
function formatBytes(bytes: number) {
  if (!Number.isFinite(bytes) || bytes < 0) return ""
  if (bytes < 1000) return `${bytes}${NBSP2}B`
  const units = ["KB", "MB", "GB", "TB"]
  let value = bytes / 1000
  let unit = 0
  while (value >= 1000 && unit < units.length - 1) {
    value /= 1000
    unit += 1
  }
  return `${value < 10 ? value.toFixed(1) : Math.round(value)}${NBSP2}${units[unit]}`
}

/** `3.4 MB/s`. */
export function formatSpeed(bytesPerSecond: number) {
  return `${formatBytes(Math.max(0, bytesPerSecond))}/s`
}

/**
 * Time left, rounded more coarsely as it grows so it settles instead of flickering:
 * whole seconds under 10 s, steps of 5 s under a minute, 10 s under 10 minutes, then minutes.
 */
export function formatTimeLeft(seconds: number) {
  if (!Number.isFinite(seconds) || seconds < 0) return ""
  if (seconds < 1.5) return "Almost done"
  if (seconds < 10) return `${Math.ceil(seconds)}${NBSP}s left`
  if (seconds < 60) return `${Math.min(55, Math.ceil(seconds / 5) * 5)}${NBSP}s left`
  if (seconds < 600) {
    const rounded = Math.ceil(seconds / 10) * 10
    const m = Math.floor(rounded / 60)
    const s = rounded % 60
    return s === 0 ? `${m}${NBSP}m left` : `${m}${NBSP}m ${s}${NBSP}s left`
  }
  if (seconds < 3600) return `${Math.ceil(seconds / 60)}${NBSP}m left`
  const h = Math.floor(seconds / 3600)
  return `${h}${NBSP}h ${Math.ceil((seconds % 3600) / 60)}${NBSP}m left`
}

/* -------------------------------------------------------------------------------------------------
 * Small parts
 * -----------------------------------------------------------------------------------------------*/

function ProgressBar({
  value,
  label,
  valueText,
  className,
}: {
  value: number
  label: string
  valueText?: string
  className?: string
}) {
  const pct = Math.round(clamp01(value) * 100)
  return (
    <div
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={pct}
      aria-valuetext={valueText ?? `${pct}%`}
      data-slot="upload-queue-progress"
      className={cn("bg-(color:--chatcn-fill-active) h-1 overflow-hidden rounded-full", className)}
    >
      <div
        className={cn(
          "bg-(color:--chatcn-accent) h-full w-full origin-left rounded-full rtl:origin-right",
          // Linear: progress maps to bytes, not to a feeling.
          "transition-transform duration-200 ease-linear motion-reduce:transition-none",
        )}
        style={{ transform: `scaleX(${clamp01(value)})` }}
      />
    </div>
  )
}

/**
 * The only shimmer in chatcn: a status label such as "Thinking". Static under reduced motion.
 * Pass `active={false}` to settle it into plain subtle text.
 */
function ShimmerText({
  active = true,
  className,
  ...props
}: React.ComponentProps<"span"> & { active?: boolean }) {
  return (
    <span
      data-slot="shimmer-text"
      className={cn("font-medium", active ? "chatcn-shimmer" : "text-(color:--chatcn-fg-subtle)", className)}
      {...props}
    />
  )
}

let context: CanvasRenderingContext2D | null | undefined

/** A text measurer that matches an element's font, from one shared canvas. */
function measurerFor(element: HTMLElement) {
  if (context === undefined) context = document.createElement("canvas").getContext("2d")
  const ctx = context
  if (!ctx) return null
  const style = getComputedStyle(element)
  const spacing = Number.parseFloat(style.letterSpacing) || 0
  const font = `${style.fontStyle} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`
  return {
    spacing,
    measure: (value: string) => {
      ctx.font = font
      if ("letterSpacing" in ctx) ctx.letterSpacing = `${spacing}px`
      return ctx.measureText(value).width
    },
  }
}

/**
 * Splits a file name into its stem and extension (with the dot). Dotfiles, and names whose last
 * "extension" is really a sentence (`notes v2. final`), keep everything in the stem.
 */
function splitChatcnFileName(name: string): { stem: string; ext: string } {
  const dot = name.lastIndexOf(".")
  if (dot <= 0 || name.length - dot > 10 || /\s/.test(name.slice(dot))) {
    return { stem: name, ext: "" }
  }
  return { stem: name.slice(0, dot), ext: name.slice(dot) }
}

/**
 * The end of the stem worth keeping beside the extension: the last word when it is short
 * (`2026` in `quarterly-report-2026.pdf`), else the last four characters.
 */
function stemTail(stem: string) {
  const word = /[\s\-_.]([^\s\-_.]{2,8})$/.exec(stem)?.[1]
  const tail = word ?? stem.slice(-4).replace(/^[\s\-_.]+/, "")
  return stem.length - tail.length >= 4 ? tail : ""
}

const SEPARATORS = /[\s\-_.]+$/

const ELLIPSIS = "…"

/**
 * Truncates `text` in the middle so it fits `maxWidth`, as one string, so the ellipsis sits flush
 * against both halves: `quarterly-rep…2026.pdf`. The extension is never cut. `measure` returns
 * the rendered width of a string. Exported for tests and for canvas or SVG labels.
 */
function middleTruncateChatcn(
  text: string,
  maxWidth: number,
  measure: (value: string) => number,
): string {
  if (maxWidth <= 0 || measure(text) <= maxWidth) return text
  const { stem, ext } = splitChatcnFileName(text)
  const keep = stemTail(stem)
  // Prefer a tail that tells similar files apart; drop to the bare extension when room is short.
  const tails = keep ? [keep + ext, ext] : [ext]
  for (const [index, tail] of tails.entries()) {
    const headMax = text.length - tail.length
    const minHead = index < tails.length - 1 ? Math.min(6, headMax) : 1
    const join = (n: number) => {
      const head = text.slice(0, n)
      return (head.replace(SEPARATORS, "") || head) + ELLIPSIS + tail
    }
    let lo = 0
    let hi = headMax
    while (lo < hi) {
      const mid = Math.ceil((lo + hi) / 2)
      if (measure(join(mid)) <= maxWidth) lo = mid
      else hi = mid - 1
    }
    if (lo >= minHead) return join(lo)
  }
  return ELLIPSIS + ext
}

const useIsoLayoutEffect = typeof window === "undefined" ? React.useEffect : React.useLayoutEffect

/**
 * Middle truncation that reflows with its container. Render it like this, so the name keeps its
 * full width as the element's natural size (chips still hug long names) and screen readers hear
 * the whole name, while the eye sees the shortened one:
 *
 * ```tsx
 * const name = useChatcnMiddleTruncate(file.name)
 * <span ref={name.ref} title={name.title} className="block min-w-0 overflow-hidden whitespace-nowrap">
 *   <span ref={name.textRef} style={name.textStyle} aria-hidden="true" dir="auto">{name.text}</span>
 *   <span dir="auto" className="block h-0 overflow-hidden">{file.name}</span>
 * </span>
 * ```
 *
 * Measures with a canvas once per width change (a ResizeObserver feeds the width, so there is
 * no layout read in the loop), then checks the rendered line once and corrects a sub-pixel
 * overshoot. The part of a glyph that no longer fits is spread as tracking too small to see
 * (at most 0.4 px a glyph), so a shortened name ends exactly at its box and whatever sits beside
 * it keeps the same gap as beside a full name. Pass `textStyle` to the visible span for that.
 * Works in either direction: the text keeps its own direction through `dir="auto"`.
 */
function useChatcnMiddleTruncate(value: string) {
  const ref = React.useRef<HTMLSpanElement>(null)
  const textRef = React.useRef<HTMLSpanElement>(null)
  const [fit, setFit] = React.useState<{ source: string; text: string; tracking?: string }>({
    source: value,
    text: value,
  })
  const width = React.useRef(-1)
  const corrections = React.useRef(0)

  const run = React.useCallback(
    (available: number) => {
      const element = ref.current
      if (!element || available <= 0) return
      width.current = available
      const measurer = measurerFor(element)
      if (!measurer) return
      const text = middleTruncateChatcn(value, available, measurer.measure)
      let tracking: string | undefined
      if (text !== value) {
        const slack = available - measurer.measure(text) - 0.5
        const extra = Math.min(Math.max(slack / Array.from(text).length, 0), 0.4)
        if (extra > 0.01) tracking = `${(measurer.spacing + extra).toFixed(3)}px`
      }
      setFit((current) =>
        current.source === value && current.text === text && current.tracking === tracking
          ? current
          : { source: value, text, tracking },
      )
    },
    [value],
  )

  useIsoLayoutEffect(() => {
    const element = ref.current
    if (!element) return
    corrections.current = 0
    run(element.getBoundingClientRect().width)
    const observer = new ResizeObserver(([entry]) => {
      const next = entry?.contentRect.width ?? 0
      if (Math.abs(next - width.current) < 0.5) return
      corrections.current = 0
      run(next)
    })
    observer.observe(element)
    // Webfonts change every width: measure again once they are in.
    let live = true
    if (document.fonts && document.fonts.status !== "loaded") {
      document.fonts.ready.then(() => {
        if (live && ref.current) run(ref.current.getBoundingClientRect().width)
      })
    }
    return () => {
      live = false
      observer.disconnect()
    }
  }, [run])

  // Canvas and layout can disagree by a fraction of a pixel (kerning, tabular figures): one check
  // per fit, and at most two corrections, so it never loops.
  useIsoLayoutEffect(() => {
    const element = ref.current
    const line = textRef.current
    if (!element || !line || fit.text === value || corrections.current >= 2) return
    const over = line.getBoundingClientRect().width - element.getBoundingClientRect().width
    if (over > 0.25) {
      corrections.current += 1
      const real = width.current
      run(real - over - 0.5)
      width.current = real
    }
  }, [fit, value, run])

  const fresh = fit.source === value
  const text = fresh ? fit.text : value
  const truncated = text !== value
  const textStyle: React.CSSProperties | undefined =
    fresh && fit.tracking ? { letterSpacing: fit.tracking } : undefined
  return { ref, textRef, text, textStyle, truncated, title: truncated ? value : undefined }
}

/**
 * The name truncates in the middle, flush around the ellipsis, and the extension never does:
 * `subscriptions_20…q1.csv`. It keeps its own direction and hugs the start of the row, so a
 * Latin name in a right-to-left page still starts at the right edge and reads left to right.
 */
function FileName({ name, className }: { name: string; className?: string }) {
  const fit = useChatcnMiddleTruncate(name)
  return (
    <span
      ref={fit.ref}
      title={fit.title}
      data-slot="upload-queue-name"
      className={cn("block min-w-0 overflow-hidden whitespace-nowrap", className)}
    >
      <span ref={fit.textRef} style={fit.textStyle} aria-hidden="true" dir="auto">
        {fit.text}
      </span>
      <span dir="auto" className="block h-0 overflow-hidden">
        {name}
      </span>
    </span>
  )
}

interface TooltipProps {
  content: React.ReactNode
  children: React.ReactElement
  side?: "top" | "bottom" | "left" | "right"
  align?: "start" | "center" | "end"
  /** A shortcut hint shown after the label, for example `⌘C`. */
  shortcut?: React.ReactNode
}

function Tooltip({ content, children, side = "top", align = "center", shortcut }: TooltipProps) {
  return (
    <TooltipPrimitive.Root>
      <TooltipPrimitive.Trigger render={children} />
      <TooltipPrimitive.Portal>
        <TooltipPrimitive.Positioner side={side} align={align} sideOffset={6} className="z-50">
          <TooltipPrimitive.Popup
            data-slot="tooltip"
            className={cn(
              "rounded-(--chatcn-radius-sm) bg-(color:--chatcn-fg) text-[0.75rem]/[1rem] text-(color:--chatcn-bg) shadow-(--chatcn-shadow-md) flex max-w-xs origin-(--transform-origin) items-center gap-2 px-2 py-1 font-medium text-pretty",
              "ease-(--chatcn-ease-out) transition-[opacity,scale] duration-125",
              "data-[ending-style]:scale-97 data-[ending-style]:opacity-0 data-[ending-style]:duration-100 data-[starting-style]:scale-97 data-[starting-style]:opacity-0",
              // Once one tooltip is open, the next appears without animation. Reduced motion keeps
              // only the fade.
              "data-[instant]:transition-none motion-reduce:transition-opacity motion-reduce:data-[ending-style]:scale-100 motion-reduce:data-[starting-style]:scale-100",
            )}
          >
            {content}
            {shortcut ? <span className="font-normal opacity-60">{shortcut}</span> : null}
          </TooltipPrimitive.Popup>
        </TooltipPrimitive.Positioner>
      </TooltipPrimitive.Portal>
    </TooltipPrimitive.Root>
  )
}

type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

interface ButtonProps extends React.ComponentProps<"button"> {
  variant?: ButtonVariant
  size?: ButtonSize
}

const base = cn(
  "chatcn-focus inline-flex shrink-0 items-center justify-center gap-1.5 font-medium whitespace-nowrap select-none",
  "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow,scale] duration-150",
