/** One file: type icon, name with its extension kept, size, progress, speed and time left. */
export function UploadQueueItem({
  file,
  rate,
  shimmer = false,
  entering = false,
  onCancel,
  onRetry,
  onRemove,
  className,
  ...props
}: UploadQueueItemProps) {
  const { status, name, size } = file
  const Icon = KIND_ICON[fileKind(name, file.type)]
  const progress = clamp01(file.progress)
  const pct = Math.round(progress * 100)
  const left = rate && rate > 0 ? ((1 - progress) * size) / rate : undefined
  const settled = status === "done" || status === "failed" || status === "canceled"

  const sizeText = status === "uploading" ? formatBytesOf(progress * size, size) : formatBytes(size)

  let line: React.ReactNode
  if (status === "uploading") {
    // Narrow queues keep the time left and drop the speed, so the bar keeps a useful length.
    const speed =
      rate && rate > 0 ? (
        <>
          <span className="hidden @sm/upload-queue:inline">{formatSpeed(rate)}, </span>
          {formatTimeLeft(left ?? 0)}
        </>
      ) : (
        `${pct}%`
      )
    line = (
      <>
        <ProgressBar
          value={progress}
          label={`Uploading ${name}`}
          valueText={left !== undefined ? `${pct}%, ${formatTimeLeft(left)}` : `${pct}%`}
          className="min-w-8 flex-1"
        />
        <span dir="ltr" className="text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
          {speed}
        </span>
      </>
    )
  } else if (status === "processing") {
    const label = file.processingLabel ?? "Processing"
    line = shimmer ? (
      <ShimmerText className="truncate">{label}</ShimmerText>
    ) : (
      <span className="text-(color:--chatcn-fg-subtle) truncate">{label}</span>
    )
  } else if (status === "failed") {
    line = (
      <span className="text-(color:--chatcn-red) line-clamp-2 text-pretty">
        {file.error ?? "Upload failed. Check your connection and retry."}
      </span>
    )
  } else {
    line = (
      <span className="text-(color:--chatcn-fg-subtle) truncate">
        {status === "queued" ? "Queued" : status === "canceled" ? "Canceled" : "Uploaded"}
      </span>
    )
  }

  return (
    <li
      data-slot="upload-queue-item"
      data-upload-state={status}
      className={cn(
        "grid grid-cols-[1rem_minmax(0,1fr)_auto] items-center gap-x-2.5 py-2 ps-3.5 pe-2",
        entering && "motion-safe:animate-[chatcn-rise_150ms_var(--chatcn-ease-out)]",
        className,
      )}
      {...props}
    >
      <span
        className={cn(
          "row-span-2 grid size-4 place-items-center self-start pt-0.5 [&_svg]:size-4",
          status === "canceled" || status === "queued"
            ? "text-(color:--chatcn-fg-subtle)"
            : "text-(color:--chatcn-fg-muted)",
        )}
        // Keeps the glyph on the name's line height: 20 px line, 16 px icon.
        style={{ height: "1.25rem" }}
      >
        <Icon aria-hidden="true" />
      </span>

      <span className="text-[0.8125rem]/[1.25rem] flex min-w-0 items-baseline gap-3">
        <FileName
          name={name}
          className={cn(
            "flex-1 font-medium",
            status === "canceled" ? "text-(color:--chatcn-fg-subtle)" : "text-(color:--chatcn-fg)",
          )}
        />
        <span dir="ltr" className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
          {sizeText}
        </span>
      </span>

      <span className="col-start-3 row-span-2 row-start-1 flex items-center gap-0.5">
        {/* Room for two actions on every row, so sizes and actions line up in columns. */}
        <span className="flex min-w-14.5 items-center justify-end gap-0.5">
          {(status === "queued" || status === "uploading") && onCancel ? (
            <IconAction label={`Cancel ${name}`} onClick={() => onCancel(file.id)}>
              <XIcon />
            </IconAction>
          ) : null}
          {(status === "failed" || status === "canceled") && onRetry ? (
            <IconAction label={`Retry ${name}`} onClick={() => onRetry(file.id)}>
              <RotateCcwIcon />
            </IconAction>
          ) : null}
          {settled && onRemove ? (
            <IconAction label={`Remove ${name}`} onClick={() => onRemove(file.id)}>
              <XIcon />
            </IconAction>
          ) : null}
        </span>
        {/* One fixed-width status slot on every row, so actions line up in a column. */}
        <span
          data-slot="upload-queue-status"
          // Below 384 px the row's own line already says Processing, Uploaded or the error, so
          // the glyph gives its 28 px back to the file name.
          className={cn(
            "hidden size-7 shrink-0 place-items-center @sm/upload-queue:grid [&_svg]:size-4",
            status === "processing"
              ? "text-(color:--chatcn-blue)"
              : status === "done"
                ? "text-(color:--chatcn-green)"
                : "text-(color:--chatcn-red)",
          )}
        >
          {status === "processing" || status === "done" || status === "failed" ? (
            <span
              key={status}
              className="grid place-items-center motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]"
            >
              {status === "processing" ? (
                <Spinner label={`Processing ${name}`} className="size-4" />
              ) : status === "done" ? (
                <CircleCheckIcon aria-label="Uploaded" role="img" />
              ) : (
                <CircleAlertIcon aria-label="Failed" role="img" />
              )}
            </span>
          ) : null}
        </span>
      </span>

      <span className="text-[0.75rem]/[1rem] col-start-2 flex min-h-4 min-w-0 items-center gap-2.5">
        {line}
      </span>
    </li>
  )
}

export interface UploadQueueProps extends Omit<React.ComponentProps<"div">, "title"> {
  files: UploadQueueFile[]
  /** Shows a cancel button on queued and uploading files. */
  onCancel?: (id: string) => void
  /** Shows Cancel all in the header while anything is queued or uploading. */
  onCancelAll?: () => void
  /** Shows Retry on failed and canceled files. */
  onRetry?: (id: string) => void
  /** Shows Remove on settled files and on the attached chips. */
  onRemove?: (id: string) => void
  /** Replaces the header title. */
  title?: React.ReactNode
  /**
   * Once every file is done, the queue folds into a row of attachment chips. Default true.
   * `expanded` keeps the details open; the row has a button to reopen them.
   */
  collapseWhenDone?: boolean
  expanded?: boolean
  defaultExpanded?: boolean
  onExpandedChange?: (expanded: boolean) => void
  /** How long the finished list stays before folding, so the last check registers. Default 800 ms. */
