/* -------------------------------------------------------------------------------------------------
 * Rates: smoothed and shown at most once a second, so speed and time left never jitter.
 * -----------------------------------------------------------------------------------------------*/

interface RateSample {
  bytes: number
  t: number
  ema?: number
}

function useUploadRates(files: UploadQueueFile[]) {
  const samples = React.useRef(new Map<string, RateSample>())
  const shownAt = React.useRef(0)
  const latest = React.useRef<Record<string, number>>({})
  const [rates, setRates] = React.useState<Record<string, number>>({})

  React.useEffect(() => {
    const now = performance.now()
    const live = new Set<string>()
    let fresh = false
    for (const file of files) {
      if (file.status !== "uploading") continue
      live.add(file.id)
      const bytes = clamp01(file.progress) * file.size
      const prev = samples.current.get(file.id)
      let sample = file.bytesPerSecond
      if (sample === undefined && prev) {
        // Re-renders without new bytes carry no information; keep the last sample point.
        if (bytes === prev.bytes || now - prev.t < 50) continue
        sample = ((bytes - prev.bytes) / (now - prev.t)) * 1000
      }
      const ema =
        sample === undefined || sample < 0
          ? prev?.ema
          : prev?.ema === undefined
            ? sample
            : prev.ema * 0.8 + sample * 0.2
      samples.current.set(file.id, { bytes, t: now, ema })
      if (ema !== undefined) {
        if (latest.current[file.id] === undefined) fresh = true
        latest.current[file.id] = ema
      }
    }
    for (const id of samples.current.keys()) {
      if (!live.has(id)) {
        samples.current.delete(id)
        delete latest.current[id]
        fresh = true
      }
    }
    if (fresh || now - shownAt.current >= 1000) {
      shownAt.current = now
      setRates({ ...latest.current })
    }
  }, [files])

  return rates
}

/* -------------------------------------------------------------------------------------------------
 * Summary
 * -----------------------------------------------------------------------------------------------*/

function summarize(files: UploadQueueFile[], rates: Record<string, number>) {
  const count = (s: UploadQueueStatus) => files.filter((f) => f.status === s).length
  const queued = count("queued")
  const uploading = count("uploading")
  const processing = count("processing")
  const done = count("done")
  const failed = count("failed")
  const canceled = count("canceled")
  const counted = files.filter((f) => f.status !== "canceled")
  const total = counted.reduce((sum, f) => sum + f.size, 0)
  const sent = counted.reduce(
    (sum, f) =>
      sum +
      (f.status === "done" || f.status === "processing"
        ? f.size
        : f.status === "uploading"
          ? clamp01(f.progress) * f.size
          : 0),
    0,
  )
  const waiting = files
    .filter((f) => f.status === "queued" || f.status === "uploading")
    .reduce((sum, f) => sum + (1 - clamp01(f.progress)) * f.size, 0)
  const speed = files.reduce(
    (sum, f) => sum + (f.status === "uploading" ? (rates[f.id] ?? 0) : 0),
    0,
  )
  return {
    queued,
    uploading,
    processing,
    done,
    failed,
    canceled,
    total,
    sent,
    transferring: queued + uploading > 0,
    active: queued + uploading + processing > 0,
    left: speed > 0 ? waiting / speed : undefined,
    counted: counted.length,
  }
}

const plural = (n: number, word: string) =>
  `${n.toLocaleString("en-US")} ${word}${n === 1 ? "" : "s"}`

/* -------------------------------------------------------------------------------------------------
 * AttachmentList: one row that scrolls sideways, fading only the edge that has more.
 * -----------------------------------------------------------------------------------------------*/

const FADE = 24

const ListContext = React.createContext(false)

function AttachmentList({ className, style, children, ...props }: React.ComponentProps<"div">) {
  const ref = React.useRef<HTMLDivElement>(null)
  const [fade, setFade] = React.useState({ start: false, end: false, rtl: false })

  React.useEffect(() => {
    const el = ref.current
    if (!el) return
    const measure = () => {
      const rtl = getComputedStyle(el).direction === "rtl"
      const scrolled = Math.abs(el.scrollLeft)
      const next = {
        start: scrolled > 1,
        end: scrolled + el.clientWidth < el.scrollWidth - 1,
        rtl,
      }
      setFade((prev) =>
        prev.start === next.start && prev.end === next.end && prev.rtl === next.rtl ? prev : next,
      )
    }
    measure()
    el.addEventListener("scroll", measure, { passive: true })
    const observer = new ResizeObserver(measure)
    observer.observe(el)
    // Children come and go; watch the content too.
    const mutations = new MutationObserver(measure)
    mutations.observe(el, { childList: true })
    return () => {
      el.removeEventListener("scroll", measure)
      observer.disconnect()
      mutations.disconnect()
    }
  }, [])

  const mask =
    fade.start || fade.end
      ? `linear-gradient(to ${fade.rtl ? "left" : "right"}, ${
          fade.start ? "transparent" : "black"
        } 0, black ${FADE}px, black calc(100% - ${FADE}px), ${fade.end ? "transparent" : "black"} 100%)`
      : undefined

  return (
    <ListContext.Provider value={true}>
      {/* biome-ignore lint/a11y/useSemanticElements: items are divs so they also work outside a list */}
      <div
        ref={ref}
        role="list"
        aria-label="Attachments"
        data-slot="attachment-list"
        className={cn(
          "flex [scrollbar-width:none] items-center gap-2 overflow-x-auto overscroll-x-contain [&::-webkit-scrollbar]:hidden",
          // Room for the hairline shadows, which overflow clipping would cut.
          "p-px",
          className,
        )}
        style={{ maskImage: mask, WebkitMaskImage: mask, ...style }}
        {...props}
      >
        {children}
      </div>
    </ListContext.Provider>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

type AttachmentStatus = "uploading" | "processing" | "ready" | "error"

/* -------------------------------------------------------------------------------------------------
 * Attachment
 * -----------------------------------------------------------------------------------------------*/

interface AttachmentProps extends Omit<React.ComponentProps<"div">, "onError"> {
  name: string
  /** Bytes. */
  size?: number
  /** MIME type. Picks the icon together with the extension. */
  type?: string
  /** Object or remote URL of an image preview. Shown with a hairline outline. */
  previewUrl?: string
  status?: AttachmentStatus
  /** 0 to 1 while `uploading`. */
  progress?: number
  /** Shown when `status` is `error`. Say how to fix it. Default "Upload failed". */
  error?: React.ReactNode
  /** `chip`: one line, 32 px. `card`: two lines, 56 px; images become square thumbnails. */
  variant?: "chip" | "card"
  /** Shows a remove button. Called after the 140 ms exit, so update your list in here. */
  onRemove?: () => void
  /** Shows Retry on errors. */
  onRetry?: () => void
  /** Makes the name a button, for example to open a preview. */
  onOpen?: () => void
}

function focusNeighbor(from: HTMLElement) {
  const list = from.closest("[data-slot=attachment-list]")
  const buttons = list
    ? Array.from(list.querySelectorAll<HTMLElement>("[data-slot=attachment-remove]"))
    : []
  const index = buttons.indexOf(from)
  const next = buttons[index + 1] ?? buttons[index - 1]
  if (next) {
    next.focus()
    return
  }
  // Last one gone: back to the composer, if there is one.
  from
    .closest("[data-slot=prompt-input]")
    ?.querySelector<HTMLElement>("[data-slot=prompt-input-textarea]")
    ?.focus()
}

/* -------------------------------------------------------------------------------------------------
 * Removal: opacity and scale 0.96 over 140 ms, then focus moves to a neighbor so keyboard users
 * never land on <body>.
 * -----------------------------------------------------------------------------------------------*/

const EXIT_MS = 140

function useExit(onDone?: () => void) {
  const [leaving, setLeaving] = React.useState(false)
  const timer = React.useRef<number>(undefined)
  React.useEffect(() => () => window.clearTimeout(timer.current), [])
  const leave = (event: React.MouseEvent<HTMLElement>) => {
    if (leaving) return
    const button = event.currentTarget
    const hadFocus = document.activeElement === button
    setLeaving(true)
    timer.current = window.setTimeout(() => {
      if (hadFocus) focusNeighbor(button)
      onDone?.()
    }, EXIT_MS)
  }
  return { leaving, leave }
}

const KIND_ICON2: Record<FileKind, React.ComponentType<{ className?: string }>> = {
  image: FileImageIcon,
  code: FileCodeIcon,
  sheet: FileSpreadsheetIcon,
  archive: FileArchiveIcon,
  video: FileVideoCameraIcon,
  audio: FileHeadphoneIcon,
  text: FileTextIcon,
  file: FileIcon,
}

function percent(progress: number | undefined) {
  return Math.round(Math.min(1, Math.max(0, progress ?? 0)) * 100)
}

/** Short type label for the meta line: `PDF`, `TSX`, `PNG`. */
function typeLabel(name: string, type = "") {
  const ext = extensionOf(name)
  if (ext) return ext.toUpperCase()
  const sub = type.split("/")[1]
  return sub ? sub.toUpperCase() : "File"
}

/* -------------------------------------------------------------------------------------------------
 * Progress pie: a hairline ring with a wedge that fills with the real bytes, the way Finder shows a
 * copy. It can never be mistaken for the spinner, so a percentage beside it is always believable.
 * -----------------------------------------------------------------------------------------------*/

// The wedge is a circle of radius 2.75 stroked 5.5 wide: its dash covers a 5.5 px disc.
const PIE_RADIUS = 2.75

const PIE_CIRCUMFERENCE = 2 * Math.PI * PIE_RADIUS

function ProgressRing({
  progress,
  label,
  className,
}: {
  progress: number
  label: string
  className?: string
}) {
  const value = percent(progress)
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={value}
      aria-valuetext={`${value}%`}
      data-slot="attachment-progress"
      className={cn("size-4 shrink-0 -rotate-90", className)}
    >
      <circle cx="8" cy="8" r="7" stroke="currentColor" strokeOpacity="0.4" strokeWidth="1.25" />
      <circle
        cx="8"
        cy="8"
        r={PIE_RADIUS}
        stroke="currentColor"
        strokeWidth={PIE_RADIUS * 2}
        strokeDasharray={PIE_CIRCUMFERENCE}
        strokeDashoffset={PIE_CIRCUMFERENCE * (1 - value / 100)}
        // Progress is linear: it maps to bytes, not to a feeling.
        className="transition-[stroke-dashoffset] duration-200 ease-linear motion-reduce:transition-none"
      />
    </svg>
  )
}

/**
 * Remounts its child when `swapKey` changes after the first render, so the new glyph settles in
 * with the kit's blur crossfade (opacity, scale 0.9 and 2 px blur, 150 ms) in the same footprint.
 */
function Swap({ swapKey, children }: { swapKey: string; children: React.ReactNode }) {
  const first = React.useRef(swapKey)
  const changed = first.current !== swapKey
  return (
    <span
      key={swapKey}
      className={cn(
        "absolute inset-0 grid place-items-center",
        changed &&
          "ease-(--chatcn-ease-out) transition-[opacity,scale,filter] duration-150 starting:scale-90 starting:opacity-0 starting:blur-[2px] motion-reduce:starting:scale-100 motion-reduce:starting:blur-none",
      )}
    >
      {children}
    </span>
  )
}

/**
 * A file name that truncates in the middle, flush around the ellipsis, keeping its extension:
 * `explain-analyze…queue.txt`. Chips still hug short names; the full name is in the title.
 */
function FileName2({ name }: { name: string }) {
  const fit = useChatcnMiddleTruncate(name)
  return (
    <span
      ref={fit.ref}
      title={fit.title}
      data-slot="attachment-name"
      className="block min-w-0 overflow-hidden whitespace-nowrap"
    >
      <span ref={fit.textRef} style={fit.textStyle} aria-hidden="true" dir="auto">
        {fit.text}
      </span>
      <span dir="auto" className="block h-0 overflow-hidden">
        {name}
      </span>
    </span>
  )
}

function Attachment({
  name,
  size,
  type,
  previewUrl,
  status = "ready",
  progress,
  error,
  variant = "chip",
  onRemove,
  onRetry,
  onOpen,
  className,
  ...props
}: AttachmentProps) {
  const inList = React.useContext(ListContext)
  const { leaving, leave } = useExit(onRemove)
  const kind = fileKind(name, type)
  const Icon = KIND_ICON2[kind]
  const card = variant === "card"
  const tile = card && previewUrl !== undefined
  const busy = status === "uploading" || status === "processing"
  const failed = status === "error"

  const meta = failed ? (
    (error ?? "Upload failed")
  ) : status === "uploading" ? (
    <>
      {card ? "Uploading " : null}
      <span className="tabular-nums">{percent(progress)}%</span>
    </>
  ) : status === "processing" ? (
    "Processing"
  ) : card ? (
    [typeLabel(name, type), size !== undefined ? formatBytes(size) : null]
      .filter(Boolean)
      .join(" · ")
  ) : size !== undefined ? (
    formatBytes(size)
  ) : null

  const indicator =
    status === "uploading" ? (
      <ProgressRing progress={progress ?? 0} label={`Uploading ${name}`} />
    ) : status === "processing" ? (
      <Spinner label={`Processing ${name}`} className="size-4" />
    ) : null

  const image = previewUrl ? (
    <>
      <img
        src={previewUrl}
        alt={tile ? name : ""}
        draggable={false}
        className="size-full object-cover"
      />
      {/* Hairline so light images never bleed into the surface. */}
      <span className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[inset_0_0_0_1px_var(--chatcn-alpha-400)]" />
    </>
  ) : null

  const glyph =
    failed && !previewUrl ? (
      <CircleAlertIcon />
    ) : busy ? (
      previewUrl ? (
        <span className="bg-(color:--chatcn-surface) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-sm) grid size-6 place-items-center rounded-full">
          {indicator}
        </span>
      ) : (
        indicator
      )
    ) : previewUrl ? null : (
      <Icon />
    )

  const lead = (
    <span
      data-slot="attachment-preview"
      className={cn(
        "relative grid shrink-0 place-items-center overflow-hidden",
        tile
          ? "rounded-(--chatcn-radius-lg) size-14"
          : card
            ? "rounded-(--chatcn-radius-sm) size-11"
            : "rounded-(--chatcn-radius-xs) size-6",
        card && !previewUrl && "bg-(color:--chatcn-fill)",
        failed ? "text-(color:--chatcn-red)" : "text-(color:--chatcn-fg-muted)",
        "[&_svg]:size-4",
        card && !tile && "[&_svg]:size-5",
      )}
    >
      {previewUrl ? image : null}
      <Swap swapKey={status}>{glyph}</Swap>
      {failed && previewUrl ? (
        <span className="absolute inset-0 grid place-items-center">
          <span className="bg-(color:--chatcn-surface) text-(color:--chatcn-red) shadow-(--chatcn-shadow-sm) grid size-6 place-items-center rounded-full">
            <CircleAlertIcon className="size-4" />
          </span>
        </span>
      ) : null}
    </span>
  )

  const iconButton = cn(
    "chatcn-focus grid shrink-0 place-items-center outline-none",
    "ease-(--chatcn-ease-standard) transition-[background-color,color,opacity] duration-150",
    "active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
    // Grow the hit area on touch without growing the glyph.
    "relative after:absolute after:-inset-2 after:content-[''] pointer-fine:after:hidden",
  )

  const retry =
    failed && onRetry ? (
      <button
        type="button"
        aria-label={`Retry ${name}`}
        onClick={onRetry}
        data-slot="attachment-retry"
        className={cn(
          iconButton,
          "rounded-(--chatcn-radius-xs) text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg) size-6",
        )}
      >
        <RotateCcwIcon />
      </button>
    ) : null

  const remove = onRemove ? (
    <button
      type="button"
      aria-label={`Remove ${name}`}
      onClick={leave}
      data-slot="attachment-remove"
      className={cn(
        iconButton,
        tile
          ? cn(
              "bg-(color:--chatcn-fg) text-(color:--chatcn-bg) shadow-(--chatcn-shadow-sm) absolute end-1 top-1 size-5 rounded-full [&_svg]:size-3",
              "pointer-fine:opacity-0 pointer-fine:group-focus-within/attachment:opacity-100 pointer-fine:group-hover/attachment:opacity-100",
            )
          : cn(
              "rounded-(--chatcn-radius-xs) text-(color:--chatcn-fg-subtle) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg) size-6",
              card &&
                "absolute end-1.5 top-1.5 pointer-fine:opacity-0 pointer-fine:group-focus-within/attachment:opacity-100 pointer-fine:group-hover/attachment:opacity-100",
            ),
      )}
    >
      <XIcon strokeWidth={tile ? 2 : 1.5} />
    </button>
  ) : null

  const title = onOpen ? (
    <button
      type="button"
      onClick={onOpen}
      className="chatcn-focus rounded-(--chatcn-radius-xs) flex min-w-0 text-start outline-none hover:underline"
    >
      <FileName2 name={name} />
    </button>
  ) : (
    <FileName2 name={name} />
  )

  return (
    <div
      role={inList ? "listitem" : undefined}
      aria-invalid={failed || undefined}
      data-slot="attachment"
      data-variant={variant}
      data-attachment-state={status}
      className={cn(
        "group/attachment relative shrink-0",
        "motion-safe:animate-[chatcn-tooltip-in_150ms_var(--chatcn-ease-out)]",
        "ease-(--chatcn-ease-out) transition-[opacity,scale] duration-140",
        leaving && "pointer-events-none scale-96 opacity-0 motion-reduce:scale-100",
        tile
          ? "rounded-(--chatcn-radius-lg)"
          : card
            ? "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-border) flex h-14 w-60 items-center gap-2.5 p-1.5 pe-8"
            : "rounded-(--chatcn-radius-md) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-border) inline-flex h-8 max-w-64 items-center gap-1.5 ps-1 pe-1",
        className,
      )}
      {...props}
    >
      {tile ? (
        <>
          {onOpen ? (
            <button
              type="button"
              onClick={onOpen}
              aria-label={`Open ${name}`}
              className="chatcn-focus rounded-(--chatcn-radius-lg) block"
            >
              {lead}
            </button>
          ) : (
            lead
          )}
          {failed && onRetry ? (
            <button
              type="button"
              aria-label={`Retry ${name}`}
              onClick={onRetry}
              className="chatcn-focus rounded-(--chatcn-radius-lg) absolute inset-0"
            />
          ) : null}
          {remove}
        </>
      ) : card ? (
        <>
          {lead}
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) flex min-w-0 font-medium">{title}</span>
            <span
              className={cn(
                "text-[0.75rem]/[1rem] flex min-w-0 items-center gap-1",
                failed ? "text-(color:--chatcn-red)" : "text-(color:--chatcn-fg-subtle)",
              )}
            >
              <span className="truncate">{meta}</span>
              {retry ? <span className="-my-1 ms-auto">{retry}</span> : null}
            </span>
          </span>
          {remove}
        </>
      ) : (
        <>
          {lead}
          <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) flex min-w-0 font-medium">{title}</span>
          {meta ? (
            <span
              className={cn(
                "text-[0.75rem]/[1rem] shrink-0 whitespace-nowrap",
                failed ? "text-(color:--chatcn-red)" : "text-(color:--chatcn-fg-subtle)",
              )}
            >
              {meta}
            </span>
          ) : null}
          {retry}
          {remove}
        </>
      )}
    </div>
  )
}

