/* -------------------------------------------------------------------------------------------------
 * UploadQueue
 * -----------------------------------------------------------------------------------------------*/

/**
 * Several uploads at once: an overall header with total progress, time left and Cancel all, then
 * one row per file. When every file is done the queue folds into a row of attachment chips, with
 * a button to bring the details back.
 */
export function UploadQueue({
  files,
  onCancel,
  onCancelAll,
  onRetry,
  onRemove,
  title,
  collapseWhenDone = true,
  expanded: expandedProp,
  defaultExpanded,
  onExpandedChange,
  collapseDelay = 800,
  maxHeight = 320,
  variant = "card",
  className,
  ...props
}: UploadQueueProps) {
  const rates = useUploadRates(files)
  const sum = summarize(files, rates)
  const allDone = files.length > 0 && sum.done === files.length

  // Details are open unless every file is done; then they fold after `collapseDelay`.
  const [expandedState, setExpandedState] = React.useState(defaultExpanded ?? !allDone)
  const expanded = expandedProp ?? expandedState
  const setExpanded = React.useCallback(
    (next: boolean) => {
      if (expandedProp === undefined) setExpandedState(next)
      onExpandedChange?.(next)
    },
    [expandedProp, onExpandedChange],
  )
  const wasDone = React.useRef(allDone)
  React.useEffect(() => {
    const before = wasDone.current
    wasDone.current = allDone
    if (!collapseWhenDone) return
    if (!allDone) {
      if (before && expandedProp === undefined) setExpandedState(true)
      return
    }
    if (before) return
    const id = window.setTimeout(() => setExpanded(false), collapseDelay)
    return () => window.clearTimeout(id)
  }, [allDone, collapseWhenDone, collapseDelay, expandedProp, setExpanded])

  // Rows already here at mount appear as they are; files added later fade in.
  const initialIds = React.useRef<Set<string> | null>(null)
  if (initialIds.current === null) initialIds.current = new Set(files.map((f) => f.id))

  // Announce failures and the end, never progress.
  const [announcement, setAnnouncement] = React.useState("")
  const prevStatus = React.useRef(new Map(files.map((f) => [f.id, f.status])))
  React.useEffect(() => {
    const prev = prevStatus.current
    for (const f of files) {
      const before = prev.get(f.id)
      if (before !== undefined && before !== "failed" && f.status === "failed") {
        setAnnouncement(`Upload failed: ${f.name}`)
      }
    }
    if (allDone && files.some((f) => prev.get(f.id) !== "done")) {
      setAnnouncement(`${plural(files.length, "file")} uploaded`)
    }
    prevStatus.current = new Map(files.map((f) => [f.id, f.status]))
  }, [files, allDone])

  const live = (
    <span aria-live="polite" className="sr-only">
      {announcement}
    </span>
  )

  if (files.length === 0) return null

  if (collapseWhenDone && allDone && !expanded) {
    return (
      <div
        data-slot="upload-queue"
        data-upload-queue-state="attached"
        className={cn("flex min-w-0 items-center gap-1", className)}
        {...props}
      >
        <AttachmentList className="min-w-0 flex-1">
          {files.map((f) => (
            <Attachment
              key={f.id}
              name={f.name}
              size={f.size}
              type={f.type}
              previewUrl={f.previewUrl}
              onRemove={onRemove ? () => onRemove(f.id) : undefined}
            />
          ))}
        </AttachmentList>
        <Tooltip content="Show upload details">
          <Button
            size="icon-sm"
            aria-label="Show upload details"
            aria-expanded={false}
            onClick={() => setExpanded(true)}
            className="text-(color:--chatcn-fg-subtle) pointer-coarse:size-11"
          >
            <ListIcon />
          </Button>
        </Tooltip>
        {live}
      </div>
    )
  }

  const current = Math.min(sum.counted, sum.done + sum.processing + 1)
  const tone: "active" | "done" | "failed" | "canceled" = sum.active
    ? "active"
    : sum.failed > 0
      ? "failed"
      : sum.done > 0
        ? "done"
        : "canceled"
  const heading =
    title ??
    (sum.transferring
      ? sum.counted === 1
        ? "Uploading 1 file"
        : `Uploading ${current} of ${plural(sum.counted, "file")}`
      : sum.processing > 0
        ? `Processing ${plural(sum.processing, "file")}`
        : sum.failed > 0
          ? sum.counted === 1
            ? "Upload failed"
            : `${sum.failed} of ${plural(sum.counted, "upload")} failed`
          : sum.done > 0
            ? `${plural(sum.done, "file")} attached`
            : "Uploads canceled")

  // With one file the row already shows its size, progress and time left.
  const single = files.length === 1
  const meta = single
    ? null
    : sum.transferring
      ? [
          formatBytesOf(sum.sent, sum.total),
          sum.left !== undefined ? formatTimeLeft(sum.left) : null,
        ]
          .filter(Boolean)
          .join(" · ")
      : sum.total > 0
        ? formatBytes(sum.total)
        : null

  const firstProcessing = files.find((f) => f.status === "processing")?.id

  return (
    <div
      data-slot="upload-queue"
      data-upload-queue-state={tone === "active" ? "uploading" : tone}
      data-variant={variant}
      className={cn(
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) @container/upload-queue min-w-0",
        variant === "card" &&
          "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) overflow-hidden forced-colors:outline-1 forced-colors:outline-solid",
        className,
      )}
      {...props}
    >
      <div
        data-slot="upload-queue-header"
        className="flex min-h-10 items-center gap-2.5 py-1.5 ps-3.5 pe-2 @sm/upload-queue:py-0 pointer-coarse:min-h-11"
      >
        <QueueGlyph tone={tone} />
        {/* The title never truncates: in a narrow queue the totals step down under it instead. */}
        <div className="flex min-w-0 flex-1 flex-col @sm/upload-queue:flex-row @sm/upload-queue:items-baseline @sm/upload-queue:gap-2.5">
          <h3 className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] min-w-0 truncate font-medium tabular-nums @sm/upload-queue:flex-1">
            {heading}
          </h3>
          {meta ? (
            <span
              dir="ltr"
              className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 text-start tabular-nums"
            >
              {meta}
            </span>
          ) : null}
        </div>
        {sum.transferring && onCancelAll ? (
          <Button size="sm" onClick={onCancelAll} className="pointer-coarse:h-11">
            Cancel all
          </Button>
        ) : null}
        {collapseWhenDone && allDone ? (
          <Tooltip content="Hide upload details">
            <Button
              size="icon-sm"
              aria-label="Hide upload details"
              aria-expanded={true}
              onClick={() => setExpanded(false)}
              className="text-(color:--chatcn-fg-subtle) pointer-coarse:size-11"
            >
              <ChevronsDownUpIcon />
            </Button>
          </Tooltip>
        ) : null}
      </div>

      {sum.transferring && !single ? (
        <div className="px-3.5 pb-1.5">
          <ProgressBar
            value={sum.total > 0 ? sum.sent / sum.total : 0}
            label="Total upload progress"
            valueText={
              sum.left !== undefined
                ? `${Math.round((sum.sent / Math.max(1, sum.total)) * 100)}%, ${formatTimeLeft(sum.left)}`
                : undefined
            }
          />
        </div>
      ) : null}

      <ul
        aria-label="Uploads"
        data-slot="upload-queue-list"
        style={{ maxHeight }}
        className="chatcn-scroll overflow-y-auto overscroll-contain pb-1"
      >
        {files.map((file) => (
          <UploadQueueItem
            key={file.id}
            file={file}
            rate={rates[file.id]}
            shimmer={file.id === firstProcessing}
            entering={!initialIds.current?.has(file.id)}
            onCancel={onCancel}
            onRetry={onRetry}
            onRemove={onRemove}
          />
        ))}
      </ul>
      {live}
    </div>
  )
}

export default UploadQueue

